{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "children",
      "type": "ReactNode",
      "description": "The trigger. Text children, a string or number or text written around an expression such as `Edited {when}`, are wrapped in a focusable inline span; holes such as `false` and `null` are ignored. With element children, HoverCard wires the first element, so that element does not need to accept a ref."
    },
    {
      "name": "content",
      "type": "ReactNode",
      "description": "Hover card content.",
      "required": true,
      "slotElements": [
        {
          "__element": "Text",
          "props": {
            "type": "body"
          },
          "children": "Content text"
        }
      ]
    },
    {
      "name": "placement",
      "type": "'above' | 'below' | 'start' | 'end'",
      "description": "Position relative to the anchor element. Logical: start/end resolve against the popover's own inherited direction (RTL mirrors in pure CSS).",
      "default": "'above'"
    },
    {
      "name": "alignment",
      "type": "'start' | 'center' | 'end'",
      "description": "Alignment along the placement axis. Logical: start/end resolve against the popover's own inherited direction (RTL mirrors in pure CSS).",
      "default": "'center'"
    },
    {
      "name": "delay",
      "type": "number",
      "description": "Show delay in milliseconds.",
      "default": "300"
    },
    {
      "name": "hideDelay",
      "type": "number",
      "description": "Hide delay in milliseconds.",
      "default": "200"
    },
    {
      "name": "focusTrigger",
      "type": "'auto' | 'always' | 'never'",
      "description": "When focus should open the hover card. auto opens when the trigger itself takes focus, or focus lands inside a trigger that is focusable at that moment, so a roving-tabindex member opens when the arrow keys reach it.",
      "default": "'auto'"
    },
    {
      "name": "touchTrigger",
      "type": "'auto' | 'tap' | 'none'",
      "description": "What a tap does where there is no hover. auto opens on tap unless the trigger performs an action of its own (a button, link, or form control), whose tap belongs to the control; an aria-disabled control performs none, so a tap on it opens its reason. tap always opens. none never opens on touch. A tap-opened card is dismissed by a tap outside it.",
      "default": "'auto'"
    },
    {
      "name": "isEnabled",
      "type": "boolean",
      "description": "Enables or disables the hover and focus triggers.",
      "default": "true"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible name for the hover card popup. When provided, the popup is exposed as a named role=\"dialog\"; when omitted, it falls back to role=\"group\" (a group may validly be unnamed)."
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Callback fired when hover card visibility changes. Called with true when shown and false when hidden."
    },
    {
      "name": "hasHoverIndication",
      "type": "'auto' | boolean",
      "description": "Shows a dashed underline on a text trigger. auto shows it when children is text: strings and numbers, such as `Edited {when}`, with holes such as `false` and `null` ignored. It has no effect on an element trigger, which keeps its own styling.",
      "default": "'auto'"
    },
    {
      "name": "isDefaultOpen",
      "type": "boolean",
      "description": "Whether the hover card should be shown on mount. Still dismissible."
    },
    {
      "name": "isOpen",
      "type": "boolean",
      "description": "Controlled open state. true holds the card open. false holds it closed against hover and focus. A controlled card answers Escape by calling onOpenChange(false) without closing; it closes when you set isOpen to false, and focus inside the card then returns to the trigger."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the card surface, the element that carries the hover-card theme target."
    },
    {
      "name": "className",
      "type": "string",
      "description": "Class name added to the card surface, beside the hover-card target class."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles for the card surface."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
